    });
  });

  // EDGE CASES - It's delicate
  describe('Empty Cart', () => {
    it('shows empty cart message and continue shopping button', () => {
      renderCheckout([]);
      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
      expect(screen.getByRole('button', { name: /continue shopping/i })).toBeInTheDocument();
    });
  });

  // ACCESSIBILITY - Everyone trades in Bartertown
  describe('Accessibility', () => {
    it('has proper ARIA labels on forms', () => {
      renderCheckout();
      expect(screen.getByRole('form', { name: /shipping information/i })).toBeInTheDocument();
    });

